-- Full deterministic dataset matching scripts/seed-realistic.js.
-- Run db/schema.sql first; this replaces data only and keeps its tables, views, procedures, and triggers.
USE hospital_db;

SET FOREIGN_KEY_CHECKS = 0;
TRUNCATE TABLE prescriptions;
TRUNCATE TABLE bills;
TRUNCATE TABLE appointments;
TRUNCATE TABLE admissions;
TRUNCATE TABLE rooms;
TRUNCATE TABLE doctors;
TRUNCATE TABLE patients;
TRUNCATE TABLE departments;
SET FOREIGN_KEY_CHECKS = 1;

START TRANSACTION;

-- 15 departments

-- 50 specialist doctors

-- 35 rooms

-- 500 patients with stable IDs and unique emails

-- 900 appointments: 18 per doctor, unique doctor/date/time slots

-- 450 prescriptions linked to completed appointments

