-- Expected counts: 15 departments, 50 doctors, 35 rooms, 500 patients, 900 appointments,
-- 450 prescriptions, 70 admissions (10 active), and 750 bills.
SELECT
  (SELECT COUNT(*) FROM departments) AS departments,
  (SELECT COUNT(*) FROM doctors) AS doctors,
  (SELECT COUNT(*) FROM rooms) AS rooms,
  (SELECT COUNT(*) FROM patients) AS patients,
  (SELECT COUNT(*) FROM appointments) AS appointments,
  (SELECT COUNT(*) FROM prescriptions) AS prescriptions,
  (SELECT COUNT(*) FROM admissions) AS admissions,
  (SELECT COUNT(*) FROM current_admissions) AS active_admissions,
  (SELECT COUNT(*) FROM bills) AS bills;
